import React from 'react';

// This component just needs the cart data to display totals
const OrderSummary = ({ cart }) => {
    // Handle potential missing data
    const subtotal = cart.totalPrice || 0;
    const discount = cart.discount || 0; // Use discount from cart if available, otherwise 0
    const deliveryFee = cart.deliveryFee || 0; // Add delivery fee if available
    const tax = cart.tax || 0; // Add tax if available
    const total = subtotal - discount + deliveryFee + tax;
    const itemCount = cart.items ? cart.items.reduce((sum, item) => sum + item.quantity, 0) : 0;

    const handleCheckout = () => {
        // You can implement checkout logic here
        alert('Checkout functionality to be implemented');
    };

    return (
        <aside className="order-summary">
            <h3>Order Summary</h3>
            <div className="summary-row">
                <span>Items ({itemCount})</span>
                <span>Rs. {subtotal.toFixed(2)}</span>
            </div>
            {discount > 0 && (
                <div className="summary-row">
                    <span>Discount</span>
                    <span style={{color: '#28a745'}}>- Rs. {discount.toFixed(2)}</span>
                </div>
            )}
            {deliveryFee > 0 && (
                <div className="summary-row">
                    <span>Delivery Fee</span>
                    <span>Rs. {deliveryFee.toFixed(2)}</span>
                </div>
            )}
            {tax > 0 && (
                <div className="summary-row">
                    <span>Tax</span>
                    <span>Rs. {tax.toFixed(2)}</span>
                </div>
            )}
            <div className="summary-row total">
                <span>Total</span>
                <span>Rs. {total.toFixed(2)}</span>
            </div>
            <button 
                className="checkout-btn"
                onClick={handleCheckout}
                disabled={itemCount === 0}
                style={{
                    opacity: itemCount === 0 ? 0.5 : 1,
                    cursor: itemCount === 0 ? 'not-allowed' : 'pointer'
                }}
            >
                Proceed to Checkout
            </button>
        </aside>
    );
};

export default OrderSummary;
